package io.github.capozziv.digitalbanking.transfers.bootstrap.web

import io.github.capozziv.digitalbanking.transfers.bootstrap.TransfersIntegrationTest
import org.assertj.core.api.Assertions.assertThat
import org.junit.jupiter.api.Test
import org.springframework.boot.test.web.server.LocalServerPort
import tools.jackson.databind.JsonNode

/** The OpenAPI contract generated by springdoc documents the two operations of the transfers API and their errors. */
class OpenApiIntegrationTest : TransfersIntegrationTest() {
    @LocalServerPort
    private var port: Int = 0

    private val docs: JsonNode by lazy {
        val response = ApiClient(port).get("/v3/api-docs")
        assertThat(response.status).describedAs(response.rawBody).isEqualTo(200)
        response.body!!
    }

    @Test
    fun `the contract has exactly the two operations of the spec`() {
        assertThat(operations().map { it.first }).containsExactlyInAnyOrder("POST /transfers", "GET /transfers/{id}")
    }

    @Test
    fun `the request documents the Idempotency-Key header and every status of the response table`() {
        val post = operation("POST /transfers")
        val header = post.get("parameters").single { it.get("in").asString() == "header" && it.get("name").asString() == "Idempotency-Key" }

        assertThat(header.get("required").asBoolean()).isTrue()
        val responses = post.get("responses")
        for (status in listOf("200", "201", "202", "400", "422", "503", "500")) {
            assertThat(responses.get(status)).describedAs(status).isNotNull()
        }
        val unprocessable = responses.get("422").get("description").asString()
        for (slug in listOf(
            "insufficient-available-balance",
            "transfer-failed",
            "same-account-transfer",
            "account-not-found",
            "idempotency-key-reused",
        )) {
            assertThat(unprocessable).contains("/problems/$slug")
        }
        assertThat(responses.get("503").get("description").asString()).contains("/problems/accounts-unavailable")
        assertThat(responses.get("503").get("headers").get("Retry-After")).isNotNull()
        assertThat(responses.get("400").get("description").asString()).contains("/problems/missing-idempotency-key")
    }

    @Test
    fun `get documents 404 transfer-not-found and 400 for an id that is not a UUID`() {
        val responses = operation("GET /transfers/{id}").get("responses")

        assertThat(responses.get("404").get("description").asString()).contains("/problems/transfer-not-found")
        assertThat(responses.get("400").get("description").asString()).contains("validation-error")
    }

    @Test
    fun `every operation documents 500 internal-error as Problem Details`() {
        for ((name, operation) in operations()) {
            val internalError = operation.get("responses").get("500")
            assertThat(internalError).describedAs(name).isNotNull()
            assertThat(internalError.get("content").get("application/problem+json")).describedAs(name).isNotNull()
        }
    }

    @Test
    fun `the schemas carry the transfer fields and the description limits`() {
        val schemas = docs.get("components").get("schemas")

        assertThat(schemas.get("ProblemDetail")).isNotNull()
        assertThat(schemas.get("TransferDTO").get("properties").propertyNames()).contains(
            "id",
            "sourceAccountId",
            "destinationAccountId",
            "amount",
            "description",
            "status",
            "failureReason",
            "createdAt",
            "updatedAt",
        )
        assertThat(
            schemas
                .get("RequestTransferDTO")
                .get("properties")
                .get("description")
                .get("maxLength")
                .asInt(),
        ).isEqualTo(140)
    }

    private fun operations(): List<Pair<String, JsonNode>> {
        val paths = docs.get("paths")
        return paths.propertyNames().flatMap { path ->
            paths.get(path).propertyNames().map { method -> "${method.uppercase()} $path" to paths.get(path).get(method) }
        }
    }

    private fun operation(name: String): JsonNode = operations().single { it.first == name }.second
}
